import { createHash, randomUUID } from "node:crypto";
import { inputSchema, outputSchema, type ToolInput, type ToolOutput } from "./schema.js";
import { OpenAIResponsesProvider, ProviderError, type ProviderUsage, type ToolProvider } from "./provider.js";
import { createStoredRun, type StorageAdapter } from "./storage.js";
export interface RunContext { requestId?: string; userId?: string; timeoutMs?: number; maxSchemaRetries?: number; maxOutputTokens?: number; provider?: ToolProvider; storage?: StorageAdapter; persistPayloads?: boolean; rateLimit?: (toolId: string, userId?: string) => Promise<void>; audit?: (event: { toolId: string; requestId: string; ok: boolean; durationMs: number; errorCode?: string; usage?: ProviderUsage }) => void | Promise<void>; }
export interface ToolRunResult<T> { output: T; metadata: { toolId: string; requestId: string; durationMs: number; model?: string; responseId?: string; usage?: ProviderUsage; safetyWarnings: string[]; }; }
export interface ToolDefinition<I, O> { id: string; name: string; validateInput(input: unknown): ReturnType<typeof inputSchema.safeParse>; run(input: I, context?: RunContext): Promise<ToolRunResult<O>>; }
export class ToolError extends Error { constructor(readonly code: string, readonly status: number, message: string, options?: ErrorOptions) { super(message, options); } }
const safetyWarnings: string[] = ["Performance rankings are simulated guidance, not measured experiment results."];
const safetyId = (userId?: string) => userId ? createHash("sha256").update(userId).digest("hex") : undefined;
export const tool: ToolDefinition<ToolInput, ToolOutput> = { id: "email-optimizer", name: "Email Optimizer", validateInput: (input) => inputSchema.safeParse(input), async run(input, context = {}) { const started = Date.now(); const requestId = context.requestId ?? randomUUID(); const parsed = inputSchema.safeParse(input); if (!parsed.success) throw new ToolError("INVALID_INPUT", 400, "Check the highlighted fields and try again"); try { await context.rateLimit?.("email-optimizer", context.userId); const provider = context.provider ?? new OpenAIResponsesProvider(); const result = await provider.generate(parsed.data, { requestId, timeoutMs: context.timeoutMs, maxSchemaRetries: context.maxSchemaRetries, maxOutputTokens: context.maxOutputTokens, safetyIdentifier: safetyId(context.userId) }); const output = outputSchema.parse(result.output); if (context.storage && context.userId) await context.storage.save(createStoredRun("email-optimizer", parsed.data, output, context.userId, context.persistPayloads)); const durationMs = Date.now() - started; await context.audit?.({ toolId: "email-optimizer", requestId, ok: true, durationMs, usage: result.usage }); return { output, metadata: { toolId: "email-optimizer", requestId, durationMs, model: result.model, responseId: result.responseId, usage: result.usage, safetyWarnings } }; } catch (error) { const mapped = error instanceof ToolError ? error : error instanceof ProviderError ? new ToolError(error.code, error.status, error.message, { cause: error }) : new ToolError("RUN_FAILED", 502, "The tool could not complete this request", { cause: error }); await context.audit?.({ toolId: "email-optimizer", requestId, ok: false, durationMs: Date.now() - started, errorCode: mapped.code }); throw mapped; } } };
export const run = tool.run.bind(tool); export const validateInput = tool.validateInput.bind(tool); export * from "./schema.js"; export * from "./provider.js"; export * from "./storage.js";
